import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const project=path.resolve(process.env.SKIA_WEB_ROOT||path.join(path.dirname(fileURLToPath(import.meta.url)),'..'));
const native=path.resolve(process.env.SKIA_NATIVE_DIR||path.join(project,'dist/vendor'));
const {create,globals}=await import(process.env.SKIA_WEBGPU_MODULE||'webgpu');
const {Initialize}=await import(pathToFileURL(path.join(project,'dist/lib/index.js')));
Object.assign(globalThis, globals);
const gpu=create(['backend=vulkan','enable-dawn-features=allow_unsafe_apis']);
const adapter=await gpu.requestAdapter();assert(adapter,'SwiftShader Vulkan adapter');
const info={vendor:adapter.info.vendor,architecture:adapter.info.architecture,device:adapter.info.device,description:adapter.info.description};console.log('Adapter',info);
const device=await adapter.requestDevice({requiredFeatures:[...adapter.features].filter(x=>['float32-filterable','float32-blendable','bgra8unorm-storage','texture-compression-bc','texture-compression-etc2','texture-compression-astc','rg11b10ufloat-renderable','depth32float-stencil8'].includes(x))});
const errors=[];device.addEventListener('uncapturederror',e=>{errors.push(e.error.message);console.error('GPU error',e.error.message);});
const require=createRequire(import.meta.url);const init=require(path.join(native,'canvaskit.cjs'));const K=await init({wasmBinary:fs.readFileSync(path.join(native,'canvaskit.wasm'))});
const features={graphite:typeof K.SkiaSharpMakeGraphiteDawn==='function',ganesh:typeof K.MakeWebGLContext==='function',paragraph:!!K.ParagraphBuilder,pathops:!!K.Path.MakeFromOp,skottie:typeof K.MakeManagedAnimation==='function',effects:!!K.SkiaSharpNative?.Effects,pdf:!!K._SkiaSharpDocument,fontInstance:!!K.SkiaSharpFontInstance};console.log('Native features',features);assert(Object.values(features).every(Boolean));
const S=await Initialize({CanvasKit:K,isolated:true,fonts:false});
const context=S.SKGraphiteContext.CreateDawn(device);assert(context,'real Graphite Dawn context');console.log('Graphite context created',context.MaxTextureSize);
const recorder=context.CreateRecorder();const texture=device.createTexture({size:[128,128],format:'rgba8unorm',usage:GPUTextureUsage.RENDER_ATTACHMENT|GPUTextureUsage.TEXTURE_BINDING|GPUTextureUsage.COPY_SRC|GPUTextureUsage.COPY_DST});const backend=S.SKGraphiteBackendTexture.CreateDawn(texture);const surface=S.SKSurface.CreateGraphite(recorder,backend);assert(surface,'native Graphite surface');
const paint=new S.SKPaint({Color:S.SKColors.Red,IsAntialias:true});surface.Canvas.Clear(S.SKColors.White);surface.Canvas.DrawCircle(64,64,36,paint);surface.Flush();await context.SubmitAsync();const result=await S.ReadWebGPUTexture(device,texture);const bytes=result.GetData();const pixel=(x,y)=>[...bytes.slice((y*128+x)*4,(y*128+x)*4+4)];assert.deepEqual(pixel(64,64),[255,0,0,255]);assert.deepEqual(pixel(0,0),[255,255,255,255]);console.log('Native Graphite circle pixels',pixel(64,64),pixel(0,0));
const raster=S.SKImage.FromPixels(new S.SKImageInfo(2,2),new Uint8Array([0,0,255,255,0,255,0,255,255,0,0,255,255,255,0,255]));
surface.Canvas.DrawImage(raster,0,0);surface.Flush();await context.SubmitAsync();const rendered=await S.ReadWebGPUTexture(device,texture);assert.deepEqual([...rendered.GetData().slice(0,4)],[0,0,255,255]);rendered.Dispose();
surface.Canvas.DrawImage(raster,10,10);surface.Flush();await context.SubmitAsync();const stats=recorder._native.imageCacheStats();console.log('Native image cache',stats);assert.equal(stats.Uploads,1);assert(stats.Hits>=1);raster.Dispose();recorder._native.purgeImageCache();assert.equal(recorder._native.imageCacheStats().Bytes,0);
await context.SubmitAsync();result.Dispose();paint.Dispose();surface.Dispose();backend.Dispose();recorder.Dispose();await context.DisposeAsync();texture.destroy();assert.deepEqual(errors,[]);const handles={devices:Object.keys(K.WebGPU.mgrDevice.objects).length,queues:Object.keys(K.WebGPU.mgrQueue.objects).length,textures:Object.keys(K.WebGPU.mgrTexture.objects).length};console.log('Native released handles',handles);assert.deepEqual(handles,{devices:0,queues:0,textures:0});device.destroy();fs.writeFileSync(process.env.SKIA_NATIVE_REPORT||path.join(native,'native-validation.json'),JSON.stringify({adapter:info,features,checks:['real Graphite context','native circle render','RGBA texture readback','raster image upload','bounded image cache reuse and purge','resource disposal and zero retained native device/queue/texture handles'],errors},null,2));process.exit(0);
